INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-x7md-pete313', 'stk-x7md', 'PETE 313', 'doc', '{"docs": [{"id": "stk-dr-f171149", "n": "Dr. Mustafa Al-Ramadan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "مادة PETE 313 Well Logging Term 211\nالتحضير : التحضير بداية الكلاس لكن يسامح على 10 دقايق أو أقل (يجي بعد الكلاس يكلمه)\nطريقة الشرح : سلايدات، الدكتور شرحه ممتاز لكن ليس الأفضل\nالكويزات : أخذنا كويز أول كلاس (اتوقع كنسله) و كويز في الاسبوع الثالث تقريبا بعدين 4 كويزات في اخر اسبوعين (صعوبة متوسطة) ولكن مهمة للفاينل و يشرح الدرس قبل الكويز\nالمياجر: الميجر الأول كان سهل الميجر الثاني صعب، لكن أضاف كم سؤال بونس فيه، تصحيحه منصف لكن لا تراجعه لانه بيشيل المساعدات الي كان معطيك اياها\nالفاينلات : Common صعب جدا\nالقريد النهائي: A\nالصوت:ممتاز\nإضافات :الدكتور سوا كيرف خاص فيه الدكاتره الثانيه ما سووه\nالدكتور حبيب و متفاهم مع الطلاب من ناحية الضغط\nتقدر تسأله عن أي شي في الكلاس،", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533479-pete313", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustafa-al-ramadan/171149/4", "user": "x7mD", "ts": 1642233892000, "tid": 171149, "pn": 4}}]}', 1642233892000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
